sys_script_include.script:
function GenerateAndSendStakeholderInvitation(vStakeholder)
{
	var GetProperty = x_snc_devtools.GetProperty;
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetUserRecord = x_snc_devtools.GetUserRecord;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var IsValidEmail = x_snc_devtools.IsValidEmail;
	var SendMail = x_snc_devtools.SendMail;
	var GetInstanceName = x_snc_devtools.GetInstanceName;
	var HtmlEncode = x_snc_devtools.HtmlEncode;


	// Check system property
	if (GetProperty('glide.email.smtp.active') == false)
	{
		return false;
	}

	var grStakeholder = GetStakeholderRecord(vStakeholder);
	if (IsValidRecord(grStakeholder) == false)
	{
		return false;
	}

	var grUser = GetUserRecord(grStakeholder.user);
	if (IsValidRecord(grUser) == false)
	{
		return false;
	}

	// Check email
	var strEmail = GetStringValue(grUser.email);
	if (IsValidEmail(strEmail) == false)
	{
		return false;
	}	

	var strMessage = GenerateStakeholderInvitation(grStakeholder);
	if (strMessage == false)
	{
		return false;
	}

	var grProcess = GetBusinessProcessRecord(grStakeholder.business_process);
	if (IsValidRecord(grProcess) == false)
	{
		return false;
	}
	var strProcessName = GetStringValue(grProcess.name);	


	var bSuccess = SendMail(
		{
			recipients: strEmail,
			subject: 'Interview regarding business process "'+strProcessName+'"',
			from: GetInstanceName(),
			body: HtmlEncode(strMessage),
		});

	if (bSuccess == false)
	{
		return false;
	}

	return true;

}
